using Marten;
using Wolverine;
using Allocation.Contracts;
using Allocation.Views;

namespace Allocation.Slices.Allocation;

/// <summary>
/// The Automated Trigger of issue-grant: <c>Event(s) -> View -> TRIGGER -> Command -> Event(s)</c>.
///
/// It is a peer of a person at a screen — it reads a View and issues a Command. It never takes an event as
/// input and never appends one; <c>Event -> Processor -> Event</c> is the classic anti-pattern.
///
/// <see cref="IQuerySession"/> and not <see cref="IDocumentSession"/> on purpose: that makes "a trigger
/// never appends" a compile error rather than a convention. The events come from the decider, reached
/// through the command.
///
/// Returns <see cref="Task"/> and NOT a result object. Wolverine treats a handler's return value as a
/// CASCADING MESSAGE with no opt-out, so a report returned from a fire-and-forget run is unroutable and
/// takes the whole outgoing batch with it. If a human needs to see what a run did, log it or give the run
/// its own operational route.
///
/// What wakes this is NOT here: see IssueGrantWakeup.
/// </summary>
public static class GrantIssuer
{
    public static async Task Handle(
        RunIssueGrant message,
        IQuerySession session,
        IMessageBus bus,
        ILogger logger,
        CancellationToken cancellation)
    {
        // THE TODO LIST. It selects on status alone, never on "recently", so a run repeated for any reason
        // — a redelivery, a replay, a restarted host — does exactly the same work and the decider's
        // AlreadyIssued absorbs whatever is no longer outstanding.
        var work = await session.Query<SlotsToIssue>()
            .Where(r => r.Status == WorkStatus.Pending)
            .ToListAsync(cancellation);

        foreach (var row in work)
        {
            // InvokeAsync and not PublishAsync: the outcome comes back, so a refusal is visible in the log
            // of THIS run rather than only in the store. It also means one row's failure cannot silently
            // stall the rest, since each is its own transaction.
            var outcome = await bus.InvokeAsync<SliceOutcome>(
                new IssueGrant(row.GrantId, row.PoolId, row.SlotNumber), cancellation);

            if (!outcome.Accepted)
                logger.LogInformation(
                    "issue-grant: grant {GrantId} not executed — {Outcome}.", row.GrantId, outcome);
        }

        // LOG EVERY RUN, INCLUDING ONE THAT DID NOTHING. Without this line "alive with no work" and "dead"
        // produce byte-identical output, and that ambiguity has hidden a broken wakeup in this kit before.
        logger.LogInformation("issue-grant: {Count} reservation(s) awaiting execution.", work.Count);
    }
}
